function make() {
  let n = 1;
  return {
    add() {
      n += 1;
    },
    read() {
      return n;
    },
  };
}
const box = make();
box.add();
console.log(box.read());

function make() {
  let n = 0;
  return function () {
    n += 1;
    return n;
  };
}
const a = make();
const b = make();
console.log(a());
console.log(b());
console.log(a());

const fns = [];
for (var i = 0; i < 2; i += 1) {
  let n = i;
  fns.push(function () {
    return n;
  });
}
console.log(fns[0]());
console.log(fns[1]());

function make() {
  let n = 1;
  const read = function () {
    return n;
  };
  n = 2;
  return read;
}
console.log(make()());

